    expect(delta.ops[0].insert).toBe('Test');
    expect(delta.ops[0].attributes).toBeUndefined();
  });

  test('nested color styles without color format drops color', () => {
    const container = document.body.appendChild(document.createElement('div'));
    container.innerHTML = '<p>dummy</p>';
