    expect(delta.ops[0].attributes).toBeUndefined();
    expect(delta.ops[1].insert).toBe('Italic');
    expect(delta.ops[1].attributes).toBeUndefined();
    expect(delta.ops[2].insert).toBe('Strike');
    expect(delta.ops[2].attributes).toBeUndefined();
  });

  test('bold/italic with formats keeps them', () => {
    const container = document.body.appendChild(document.createElement('div'));
    container.innerHTML = '<p>dummy</p>';
